EDITS = [('tests/old-interrupt-close.sps', '(define one-ms (duration 1))', '(define one-ms (duration 1))\n(define planted-sleep\n  (let ((calls 0))\n    (lambda (t)\n      (set! calls (+ calls 1))\n      (if (odd? calls) (error \'sleep "planted: raises on every odd call") (sleep t)))))'), ('tests/old-interrupt-close.sps', '                   (unless started (set! started #t) (condition-broadcast c)))\n                 (sleep one-ms)', '                   (unless started (set! started #t) (condition-broadcast c)))\n                 (planted-sleep one-ms)')]
